/* Panda Go HSK 1 v184 — original native Mandarin recordings from the course owner. */
/* Nine newly mapped unique phrases from the first delivered recording. */
/* No cloning, re-synthesis, voice conversion or re-encoding of the original MP3 files. */
(()=>{
'use strict';
const voices=window.PANDA_HSK1_VOICES;
if(!voices || !voices.female || !voices.male)return;
const nativeClips=
{"下雪":"data:audio/mpeg;base64,","两个人":"data:audio/mpeg;base64,","九":"data:audio/mpeg;base64,","九月":"data:audio/mpeg;base64,","二":"data:audio/mpeg;base64,","二十三":"data:audio/mpeg;base64,","二月":"data:audio/mpeg;base64,","二零二六年十一月六日":"data:audio/mpeg;base64,","五":"data:audio/mpeg;base64,"};
for(const [phrase,src] of Object.entries(nativeClips)){
  voices.female[phrase]=src;
  voices.male[phrase]=src;
}
// For every full sentence already recorded in the second take, use the same
// authorized human speaker for both roles, rather than changing voices mid-dialogue.
const previous=window.PANDA_HSK1_USER_VOICE_V183;
if(previous && Array.isArray(previous.mappedKeys)){
  for(const phrase of previous.mappedKeys){
    const native=voices.female[phrase];
    if(typeof native==='string' && native.startsWith('data:audio/mpeg;base64,')){
      voices.male[phrase]=native;
    }
  }
}
window.PANDA_HSK1_USER_VOICE_V184=Object.freeze({
  nativeSpeaker:'same female native speaker, user supplied',
  firstRecordingUniqueCount:9,
  secondRecordingUniqueCount:35,
  firstRecordingPhrases:Object.freeze(Object.keys(nativeClips)),
  incomplete:true,
  comment:'Only available human recordings are mapped; synthesized audio remains for unrecorded phrases.'
});
})();